/**
 * The guard every server-side request this package makes for someone else's
 * URL goes through: `WebPage.check` and `Docs.fetchText` both refuse what it
 * refuses, before anything is sent and on every redirect.
 *
 * @since 0.1.0
 * @private
 */
const LOCAL_SUFFIXES = [".localhost", ".local", ".internal", ".home.arpa", ".lan"];
/**
 * Why a request to `url` is refused, or nothing: `invalid_url` for anything
 * but `http:` or `https:`, or a URL with a user or a password;
 * `private_host` for an IP address literal however it is spelled, a
 * single-label name, or a name under a local suffix, unless `privateHosts`
 * names its host.
 *
 * @since 0.1.0
 * @private
 */
export const refusal = (url, privateHosts) => {
    if (url.protocol !== "https:" && url.protocol !== "http:")
        return "invalid_url";
    if (url.username !== "" || url.password !== "")
        return "invalid_url";
    const hostname = url.hostname.toLowerCase();
    if (privateHosts.includes(hostname))
        return undefined;
    const name = hostname.replace(/\.$/, "");
    // The URL parser writes every IPv4 spelling (`2130706433`, `0x7f.1`) as four decimals, and IPv6 in brackets.
    const literal = name.startsWith("[") || /^\d+\.\d+\.\d+\.\d+$/.test(name);
    const local = !name.includes(".") || LOCAL_SUFFIXES.some((suffix) => name.endsWith(suffix));
    return literal || local ? "private_host" : undefined;
};
